// Volatility Compression Release 3D
// ATR + range coiling + vol-of-vol rise -> coil load + tape predictability, release-gated signals.

atrLen = input(14, "ATR Length", 2, 60, 1)
coilLookback = input(60, "Coil Lookback", 20, 240, 1)
volLen = input(20, "VolOfVol Lookback", 5, 100, 1)
volRiseLag = input(5, "VolOfVol Rise Lag", 1, 30, 1)
predLen = input(20, "Predictability Lookback", 5, 100, 1)
loadThreshold = input(0.65, "Load Threshold", 0.0, 1.0, 0.05)
predictThreshold = input(0.60, "Predictability Threshold", 0.0, 1.0, 0.05)
releaseRangeMult = input(1.50, "Release Range Mult", 1.0, 3.0, 0.1)
releaseBufferAtrMult = input(0.15, "Release Buffer ATR Mult", 0.0, 1.0, 0.05)
loadCompWeight = input(0.50, "Load Compression Weight", 0.0, 1.0, 0.05)
loadVolWeight = input(0.50, "Load VolOfVol Weight", 0.0, 1.0, 0.05)
pointSize = input(2.0, "3D Point Size", 0.2, 3.0, 0.1)

// Core volatility series
rng = high - low
atrVal = atr(high, low, close, atrLen) // ATR: built-in Wilder RMA — validated vs TradingView

// Vol-of-vol level
vvAtr = highest(atrVal, volLen) - lowest(atrVal, volLen)
vvRng = highest(rng, volLen) - lowest(rng, volLen)
v = vvAtr + vvRng

delta = 0.0
if bar_index >= volRiseLag {
    delta = v - v[volRiseLag]
}

// Percentile ranks over Coil Lookback, current bar included
rrRank = 0.0
arRank = 0.0
vRise = 0.0

if bar_index >= coilLookback - 1 {
    cntRR = 0
    cntAR = 0
    cntDelta = 0
    for i = 0 to coilLookback - 1 {
        if rng[i] <= rng { cntRR = cntRR + 1 }
        if atrVal[i] <= atrVal { cntAR = cntAR + 1 }
        if delta[i] <= delta { cntDelta = cntDelta + 1 }
    }
    rrRank = cntRR / coilLookback
    arRank = cntAR / coilLookback
    vRise = cntDelta / coilLookback
} else {
    avail = bar_index + 1
    cntRR = 0
    cntAR = 0
    cntDelta = 0
    for i = 0 to avail - 1 {
        if rng[i] <= rng { cntRR = cntRR + 1 }
        if atrVal[i] <= atrVal { cntAR = cntAR + 1 }
        if delta[i] <= delta { cntDelta = cntDelta + 1 }
    }
    rrRank = cntRR / avail
    arRank = cntAR / avail
    vRise = cntDelta / avail
}

// Coil Load and Tape Predictability readings
compression = ((1 - rrRank) + (1 - arRank)) / 2
load = loadCompWeight * compression + loadVolWeight * vRise

alignment = 1 - abs(arRank - rrRank)
predict = lowest(alignment, predLen)

// Release frame: prior coil box excludes the current bar
coilHigh = highest(high[1], coilLookback)
coilLow = lowest(low[1], coilLookback)
coilRangeFloor = max(lowest(rng[1], coilLookback), 0.0001)
coilAtrFloor = max(lowest(atrVal[1], coilLookback), 0.0001)

expansion = rng / coilRangeFloor
longBreak = close > coilHigh + releaseBufferAtrMult * coilAtrFloor
shortBreak = close < coilLow - releaseBufferAtrMult * coilAtrFloor

// Signal gates use prior-bar load/predictability to avoid lookahead
warmup = bar_index >= coilLookback + volLen + volRiseLag + predLen
loadGatePrev = load[1] >= loadThreshold
predGatePrev = predict[1] >= predictThreshold
releaseUp = warmup and loadGatePrev and expansion >= releaseRangeMult and longBreak
releaseDn = warmup and loadGatePrev and expansion >= releaseRangeMult and shortBreak

releaseUpEdge = releaseUp and not releaseUp[1]
releaseDnEdge = releaseDn and not releaseDn[1]

buySig = releaseUpEdge and predGatePrev
buyAlertSig = releaseUpEdge and not predGatePrev
sellSig = releaseDnEdge and predGatePrev
sellAlertSig = releaseDnEdge and not predGatePrev

// 2D + 3D signal markers
if buySig {
    plotshape(bar_index, low, "Buy Loaded Predictable", "triangleup", "#22cc88")
    plotshape_3d(bar_index, load, "Buy Loaded Predictable 3D", "coneup", "#22cc88", pointSize, 1, "separate", 0, 0, 0)
}
if buyAlertSig {
    plotshape(bar_index, low, "Buy Loaded Unpredictable", "triangleup", "#889988")
    plotshape_3d(bar_index, load, "Buy Loaded Unpredictable 3D", "coneup", "#889988", pointSize, 0, "separate", 0, 0, 0)
}
if sellSig {
    plotshape(bar_index, high, "Sell Loaded Predictable", "triangledown", "#ff4477")
    plotshape_3d(bar_index, load, "Sell Loaded Predictable 3D", "conedown", "#ff4477", pointSize, 1, "separate", 0, 0, 0)
}
if sellAlertSig {
    plotshape(bar_index, high, "Sell Loaded Unpredictable", "triangledown", "#997788")
    plotshape_3d(bar_index, load, "Sell Loaded Unpredictable 3D", "conedown", "#997788", pointSize, 0, "separate", 0, 0, 0)
}

// 2D readings in the lower pane + 3D surfaces in the separate 3D pane
plot(load, "Coil Load", "#22aaff", 2, "separate")
plot(predict, "Tape Predictability", "#ffcc44", 1, "separate")

plot3d(load, "Coil Load 3D", "surface", "#22aaff", "separate", 0)
plot3d(predict, "Tape Predictability 3D", "ribbon", "#ffcc44", "separate", 1)

// 2D main-chart coil-load candle tint: neutral to bright as load rises
loadColor = "#333333"
if load >= 0.30 { loadColor = "#445555" }
if load >= 0.45 { loadColor = "#557788" }
if load >= 0.60 { loadColor = "#66aa99" }
if load >= 0.75 { loadColor = "#88ccbb" }
if load >= 0.90 { loadColor = "#ffffff" }
barcolor(loadColor)
